description:
For an IOCTL with a given method and lengths, work out what lesson 2.04 says the driver receives:

```cpp
struct BufferPlan
{
    std::uint32_t systemBufferSize;   // 0 if there is no system buffer
    bool inputInSystemBuffer;
    bool outputInSystemBuffer;
    bool outputAsMdl;
    bool rawUserPointers;
};

BufferPlan planFor(std::uint32_t method, std::uint32_t inLength, std::uint32_t outLength);
std::uint32_t bytesCopiedBack(std::uint32_t method, std::uint32_t outLength, std::uint64_t information);
```

- `METHOD_BUFFERED` (0): one system buffer of `max(in, out)` bytes holds the input and receives the output.
- `METHOD_IN_DIRECT` (1) and `METHOD_OUT_DIRECT` (2): the input (if any) is in a system buffer of `in` bytes; the output buffer (if `out > 0`) comes as an MDL.
- `METHOD_NEITHER` (3): no system buffer; raw user pointers.
- `bytesCopiedBack`: only buffered I/O copies output back: `min(information, outLength)`. The direct methods wrote straight into the user's pages (0 copied), and neither I/O copies nothing either.

starter.solution.cpp:
#include <cstdint>

struct BufferPlan { std::uint32_t systemBufferSize; bool inputInSystemBuffer; bool outputInSystemBuffer; bool outputAsMdl; bool rawUserPointers; };

BufferPlan planFor(std::uint32_t method, std::uint32_t inLength, std::uint32_t outLength) { return {}; }
std::uint32_t bytesCopiedBack(std::uint32_t method, std::uint32_t outLength, std::uint64_t information) { return 0; }

solution.solution.cpp:
#include <algorithm>
#include <cstdint>

struct BufferPlan { std::uint32_t systemBufferSize; bool inputInSystemBuffer; bool outputInSystemBuffer; bool outputAsMdl; bool rawUserPointers; };

BufferPlan planFor(std::uint32_t method, std::uint32_t inLength, std::uint32_t outLength)
{
    switch (method)
    {
    case 0: { const std::uint32_t size{ std::max(inLength, outLength) }; return { size, inLength > 0, outLength > 0, false, false }; }
    case 1:
    case 2: return { inLength, inLength > 0, false, outLength > 0, false };
    default: return { 0, false, false, false, true };
    }
}

std::uint32_t bytesCopiedBack(std::uint32_t method, std::uint32_t outLength, std::uint64_t information)
{
    if (method != 0) return 0;
    return static_cast<std::uint32_t>(std::min<std::uint64_t>(information, outLength));
}

unitTests:
TEST("buffered") {
    BufferPlan p = planFor(0, 16, 64); CHECK_EQ(p.systemBufferSize, 64u); CHECK(p.inputInSystemBuffer); CHECK(p.outputInSystemBuffer); CHECK(!p.outputAsMdl);
    p = planFor(0, 100, 8); CHECK_EQ(p.systemBufferSize, 100u); p = planFor(0, 0, 0); CHECK_EQ(p.systemBufferSize, 0u); CHECK(!p.inputInSystemBuffer);
}
TEST("direct") { BufferPlan p = planFor(2, 16, 1 << 20); CHECK_EQ(p.systemBufferSize, 16u); CHECK(p.outputAsMdl); CHECK(!p.outputInSystemBuffer); p = planFor(1, 0, 4096); CHECK(!p.inputInSystemBuffer); CHECK(p.outputAsMdl); }
TEST("neither") { const BufferPlan p = planFor(3, 16, 16); CHECK(p.rawUserPointers); CHECK_EQ(p.systemBufferSize, 0u); }
TEST("copied back") { CHECK_EQ(bytesCopiedBack(0, 64, 16), 16u); CHECK_EQ(bytesCopiedBack(0, 8, 100), 8u); CHECK_EQ(bytesCopiedBack(2, 4096, 4096), 0u); CHECK_EQ(bytesCopiedBack(3, 16, 16), 0u); }

